			rts
do13_t_go:			lea do13_t, sp
			rts
do14_t_go:			lea do14_t, sp
			rts

p_runsort_c:		; call runsort
			clr.l var_runsort_m
			clr.w var_runsort_prev
			clr.w var_runsort_v
			move.l sp, p_runsort_rs
			lea p_runsort, sp
			rts
p_runsort_r:		; end of runsort
			movea.l p_runsort_rs, sp
			rts
p_secs_c:		; call secs
			movea.l (sp)+, a0		; t
			move.w (a0), var_secs_t
			clr.b var_secs_secs
			move.l sp, p_secs_rs
			lea p_secs, sp
			rts
p_secs_r:		; end of secs
			movea.l p_secs_rs, sp
			rts

