;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## ntc_d_inbuf @data

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_ifzero
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero:
			movea.l (sp)+, a0
			tst.w (a0)
			beq kw_giz_go
			addq.l #4, sp
			rts
kw_giz_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d1
			cmp.w (a0), d1
			blt ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_next1v ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			addq.w #1, (a0)
			bvs ntc_for_skip
			move.w (a1), d1
			cmp.w (a0), d1
			bge ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			seq d0
			ext.w d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

; ============================================================
; Arithmetic (16 bit, wrapping)
; ============================================================

			even
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			add.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_subvv
;kw_subvv, <var1>, <var2>, <destvar>  - var1 - var2
kw_subvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvl
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			muls.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_div
; d0.w / d1.w signed, truncating: d0.w = quotient, d1.w = remainder (the
; dividend's sign). Divide by zero: quotient 0, remainder = dividend.
; -32768 / -1: quotient -32768, remainder 0 (as the Z80 library). jmp (a6)
ntc_div:
			tst.w d1
			beq ntc_div_z
			ext.l d0
			move.l d0, d2
			divs.w d1, d0
			bvs ntc_div_ov
			move.l d0, d1
			swap d1
			jmp (a6)
ntc_div_z:
			move.w d0, d1
			moveq #0, d0
			jmp (a6)
ntc_div_ov:
			move.w #$8000, d0
			moveq #0, d1
			jmp (a6)

			even
;## kw_divvv ntc_div
;kw_divvv, <var1>, <var2>, <destvar>  - var1 \ var2
kw_divvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_div_q, a6
			bra ntc_div
kw_div_q:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_divvl ntc_div kw_divvv
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			lea kw_div_q, a6
			bra ntc_div

			even
;## kw_modvv ntc_div
;kw_modvv, <var1>, <var2>, <destvar>  - var1 MOD var2
kw_modvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_mod_r, a6
			bra ntc_div
kw_mod_r:
			movea.l (sp)+, a0
			move.w d1, (a0)
			rts

			even
;## kw_modvl ntc_div kw_modvv
kw_modvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			lea kw_mod_r, a6
			bra ntc_div

			even
;## kw_andvl
kw_andvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			and.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_orvv
kw_orvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			or.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scpltvv ntc_cmp
kw_scpltvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_slt

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
kw_sc_end:
			tst.b (a1)
			beq kw_sc_copy
			addq.l #1, a1
			subq.w #1, d1
			bgt kw_sc_end
			rts
kw_sc_copy:
			tst.w d1
			beq kw_sc_none
			subq.w #1, d1
kw_sc_lp:
			move.b (a0)+, (a1)+
			dbeq d1, kw_sc_lp
			beq kw_sc_none
			clr.b (a1)
kw_sc_none:
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and backspace, on the real stack (jsr). a2 = buffer (its
; capacity in the byte before it). 0 terminated, then a new line.
ntc_gets:
			moveq #0, d3
			move.b -1(a2), d3			; capacity
			moveq #0, d4				; typed
ntc_gs_wait:
			jsr ntc_plat_getkey
			cmpi.b #13, d0
			beq ntc_gs_done
			cmpi.b #127, d0
			beq ntc_gs_del
			cmpi.b #8, d0
			beq ntc_gs_del
			cmpi.b #32, d0
			bcs ntc_gs_wait
			cmp.w d3, d4
			bcc ntc_gs_wait
			move.b d0, 0(a2, d4.w)
			addq.w #1, d4
			jsr ntc_plat_putc
			bra ntc_gs_wait
ntc_gs_del:
			tst.w d4
			beq ntc_gs_wait
			subq.w #1, d4
			jsr ntc_plat_backspace
			bra ntc_gs_wait
ntc_gs_done:
			clr.b 0(a2, d4.w)
			jmp ntc_plat_newline

			even
;## kw_inkeys ntc_data ntc_plat_key
;kw_inkeys, <dest>  - Inkey$: the new key press as a string, "" if none
kw_inkeys:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_scankey
			NTC_TS
			move.b d0, (a2)+
			beq kw_iks_e
			clr.b (a2)
kw_iks_e:
			rts

			even
;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame (vertical blank)
kw_frame:
			NTC_RS
			jsr ntc_plat_frame
			NTC_TS
			rts

			even
;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - the tick count (frames, 60 or 50 a second)
kw_ticks:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_ticks
			NTC_TS
			move.w d0, (a2)
			rts

; ============================================================
; String functions. Numbers are passed as the address of a word.
; Results go to a string buffer. Dest may be the same as the source.
; ============================================================

			even
;## ntc_getn
; a0 = address of a word: d0.w = its value limited to 0..255. jmp (a6). Keeps others.
ntc_getn:
			move.w (a0), d0
			bmi ntc_gn_zero
			cmpi.w #255, d0
			bls ntc_gn_ok
			move.w #255, d0
ntc_gn_ok:
			jmp (a6)
ntc_gn_zero:
			moveq #0, d0
			jmp (a6)

			even
;## kw_strleft ntc_getn
;kw_strleft, <dest>, <src>, <nvar>  - Left$(src, n)
kw_strleft:
			movea.l (sp)+, a1
			movea.l (sp)+, a2
			movea.l (sp)+, a0
			lea kw_sl_n, a6
			bra ntc_getn
kw_sl_n:
			movea.l a2, a0
; copy up to d0.w chars from a0 to a1, then the 0. rts (the thread)
ntc_strncpy:
			subq.w #1, d0
			bmi ntc_sn_end
ntc_sn_lp:
			move.b (a0)+, (a1)+
			dbeq d0, ntc_sn_lp
			beq ntc_sn_z
ntc_sn_end:
			clr.b (a1)
ntc_sn_z:
			rts

			even
;## kw_strmid ntc_getn kw_strleft
;kw_strmid, <dest>, <src>, <startvar>, <lenvar>  - Mid$(src, start, len)
kw_strmid:
			movea.l (sp)+, a1
			movea.l (sp)+, a2
			movea.l (sp)+, a0
			lea kw_sm_s, a6
			bra ntc_getn
kw_sm_s:
			tst.w d0
			beq kw_sm_s1
			subq.w #1, d0
kw_sm_s1:
			tst.w d0
			beq kw_sm_len
			tst.b (a2)
			beq kw_sm_len
			addq.l #1, a2
			subq.w #1, d0
			bra kw_sm_s1
kw_sm_len:
			movea.l (sp)+, a0
			lea kw_sm_n, a6
			bra ntc_getn
kw_sm_n:
			movea.l a2, a0
			bra ntc_strncpy

			even
;## kw_strstr ntc_itoa
;kw_strstr, <dest>, <nvar>  - Str$(n): a space before 0 and positives
kw_strstr:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.w (a0), d0
			bmi kw_st_go
			move.b #' ', (a1)+
kw_st_go:
			lea ntc_next, a6
			bra ntc_itoa

			even
;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_uc_lp:
			move.b (a0)+, d0
			cmpi.b #'a', d0
			bcs kw_uc_put
			cmpi.b #'z', d0
			bhi kw_uc_put
			subi.b #32, d0
kw_uc_put:
			move.b d0, (a1)+
			bne kw_uc_lp
			rts

			even
;## kw_l_mov
kw_l_mov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), (a1)
			rts

			even
;## kw_l_ltoi
;kw_l_ltoi, <long>, <intdest>  - Long to Integer (low 16 bits)
kw_l_ltoi:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w 2(a0), (a1)
			rts

			even
;## ntc_lcmp
; tails: d0 = a (long), d1 = b: Z if a <rel> b
ntc_lcmp_lt:
			cmp.l d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_lcmp_le:
			cmp.l d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_lcmp_gt:
			cmp.l d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_lcmp_ge:
			cmp.l d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_lcmp_ne:
			cmp.l d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_l_cplt ntc_lcmp
kw_l_cplt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_lt

			even
;## kw_l_cpgt ntc_lcmp
kw_l_cpgt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_gt

			even
;## kw_l_cpeq
kw_l_cpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			cmp.l (a1), d0
			rts

			even
;## kw_l_cpne ntc_lcmp
kw_l_cpne:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_ne

			even
;## kw_l_val
;kw_l_val, <src>, <destlong>  - Val() to a Long (decimal)
kw_l_val:
			movea.l (sp)+, a0
			movea.l (sp)+, a2
ntc_lv_go:
			moveq #0, d0
			moveq #0, d2
ntc_lv_sp:
			cmpi.b #' ', (a0)
			bne ntc_lv_sg
			addq.l #1, a0
			bra ntc_lv_sp
ntc_lv_sg:
			cmpi.b #'-', (a0)
			bne ntc_lv_dig
			moveq #1, d2
			addq.l #1, a0
ntc_lv_dig:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_lv_done
			cmpi.b #10, d1
			bcc ntc_lv_done
			move.l d0, d3
			add.l d0, d0
			add.l d0, d0
			add.l d3, d0
			add.l d0, d0				; * 10
			add.l d1, d0
			bra ntc_lv_dig
ntc_lv_done:
			tst.w d2
			beq ntc_lv_st
			neg.l d0
ntc_lv_st:
			move.l d0, (a2)
			rts

			even
;## kw_l_input ntc_gets kw_l_val ntc_d_inbuf
;kw_l_input, <destlong>  - Input to a Long
kw_l_input:
			move.l (sp)+, ntc_ivar
			lea ntc_inbuf, a2
			NTC_RS
			jsr ntc_gets
			NTC_TS
			lea ntc_inbuf, a0
			movea.l ntc_ivar, a2
			bra ntc_lv_go

			even
;## ntc_ng_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ng_boot:
			move.w #$2700, sr          ; interrupts off during setup
			move.b d0, REG_DIPSW       ; kick the watchdog (any write)     ;!!NG value
			; clear the fix layer, set up the palette and a text font in fix tiles
			jsr ntc_ng_fixclear        ; (below)
			; hand control to the thread - the compiler's start code follows;
			; it sets A7 to the thread and runs. Interrupts get re-enabled there.
			; (ntc_plat_data / screen are pulled in as deps.)
			rts

			even
;## ntc_plat_data ntc_data
ntc_curx:   dc.w 0                     ; fix-layer cursor column (0..39)
ntc_cury:   dc.w 0                     ; row (0..31)
ntc_frames: dc.w 0                     ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; the platform routines are entered with jsr and end with rts (real stack),
; keeping d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ng_fixaddr - d1.w = the VRAM word address of (ntc_curx, ntc_cury) in the
; fix map. The fix map is column-major: addr = NG_FIXMAP + col*32 + row.  ;!!NG layout
ntc_ng_fixaddr:
			move.w ntc_curx, d1
			lsl.w #5, d1               ; col * 32
			add.w ntc_cury, d1
			add.w #NG_FIXMAP, d1
			rts

; ntc_plat_putc - d0.b = character 32..126: write it as a fix tile, advance
ntc_plat_putc:
			jsr ntc_ng_fixaddr
			move.w d1, REG_VRAMADDR
			move.w #1, REG_VRAMMOD     ; (irrelevant for a single write)
			and.w #$00FF, d0
			; fix tile word = palette<<12 | char code ;!!NG tile numbering / font must be uploaded
			move.w d0, REG_VRAMRW
			addq.w #1, ntc_curx
			cmp.w #40, ntc_curx
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - CR LF: column 0, next row (scroll not done yet) ;!!NG scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #32, ntc_cury
			blt.s ntc_nl_done
			move.w #31, ntc_cury
ntc_nl_done:
			rts

; ntc_ng_fixclear - blank the whole fix layer (space tile)   ;!!NG space tile index
ntc_ng_fixclear:
			move.w #NG_FIXMAP, REG_VRAMADDR
			move.w #1, REG_VRAMMOD
			move.w #40*32-1, d1
ntc_fc_lp:
			move.w #$0020, REG_VRAMRW
			dbra d1, ntc_fc_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_data
ntc_plat_backspace:
			tst.w ntc_curx
			beq.s ntc_bs_done
			subq.w #1, ntc_curx
			jsr ntc_ng_fixaddr
			move.w d1, REG_VRAMADDR
			move.w #$0020, REG_VRAMRW
ntc_bs_done:
			rts

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0. Reads P1 (active low). Maps the stick
; to the CPC cursor codes and A/B/C to "A"/"B"/"C"; Start = 13.  ;!!NG bit map
ntc_plat_scankey:
			moveq #0, d0
			move.b REG_P1CNT, d1
			not.b d1                    ; active low -> 1 = pressed
			btst #4, d1                 ; A
			beq.s ntc_sk_b
			moveq #'A', d0
			rts
ntc_sk_b:
			btst #5, d1                 ; B
			beq.s ntc_sk_start
			moveq #'B', d0
			rts
ntc_sk_start:
			move.b REG_STATUS_B, d1
			not.b d1
			btst #0, d1                 ; Start P1
			beq.s ntc_sk_none
			moveq #13, d0
ntc_sk_none:
			rts

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_frame ntc_plat_data ntc_data
; ntc_plat_frame - called once per NTC frame; bump the counter. A real build
; waits for VBlank here (the level-? interrupt) ;!!NG wire VBlank
ntc_plat_frame:
			addq.w #1, ntc_frames
			move.b d0, REG_DIPSW        ; kick the watchdog each frame   ;!!NG
			rts

			even
;## ntc_plat_ticks ntc_plat_data ntc_data
; ntc_plat_ticks - d0.w (Integer) = the frame counter (TicksPerSecond ~ 60)
ntc_plat_ticks:
			move.w ntc_frames, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - a cart can't "exit"; spin (a real build returns to the BIOS
; menu / soft-resets) ;!!NG
ntc_plat_exit:
			bra.s ntc_plat_exit


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_want:			dc.l 0
var_nodes:			dc.w 0
var_h:			dc.l 0
var_i:			dc.w 0
for4_l:			dc.w 0
var_seed:			dc.w 0
			dc.b 40			; capacity
var_k:			ds.b 41
			even
var_t0:			dc.w 0
var_ok:			dc.w 0
var_t1:			dc.w 0
			dc.b 40			; capacity
var_secs_secs:			ds.b 41
			even
var_t2:			dc.w 0
var_t3:			dc.w 0
var_r:			dc.w 0
p_runsort_rs:			dc.l 0
var_runsort_m:			dc.l 0
var_runsort_prev:			dc.w 0
var_runsort_v:			dc.w 0
p_secs_rs:			dc.l 0
var_secs_t:			dc.w 0
tmp0:			dc.w 0
tmp1:			dc.w 0
tmp2:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			dc.b 40			; capacity
stmp1:			ds.b 41
			even
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
			dc.b 40					; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:	ds.b 41					; inputint: typed text
			even
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
